// MaxEco Node C.2: Load Quotations and Unpaid Invoices
const fs = require('fs');
const path = require('path');

const testDataPath = path.resolve(process.cwd(), 'automation/data/dummy-finance-registers.json');
let data = {};
if (fs.existsSync(testDataPath)) {
  data = JSON.parse(fs.readFileSync(testDataPath, 'utf8'));
}

return [{ json: data }];

// MaxEco Node C.3: Detect Expiring Quotes & Due Invoices (Within 3 Days or Overdue)
const data = $input.first().json;
const quotes = data.quotations || [];
const invoices = data.invoices || [];

const now = new Date();
const todayStr = now.toISOString().slice(0, 10);
const threeDaysAhead = new Date(now.getTime() + 3 * 86400000).toISOString().slice(0, 10);

const drafts = [];

// 1. Check Unpaid & Overdue Invoices
invoices.forEach(inv => {
  const uncollected = (Number(inv.amountBilled) || 0) - (Number(inv.amountCollected) || 0);
  if (uncollected > 0 && inv.dueDate <= threeDaysAhead) {
    const isOverdue = inv.dueDate < todayStr;
    const draftText = `Dear ${inv.clientName}, greeting from MaxEco Energy & Tech. This is a gentle reminder regarding invoice ${inv.id} for ₹${uncollected.toLocaleString('en-IN')}, which was due on ${inv.dueDate}. Please let us know if you need any clarification or the bank payment details. Thank you.`;

    drafts.push({
      type: 'INVOICE_PAYMENT_REMINDER',
      id: inv.id,
      clientName: inv.clientName,
      amountDue: uncollected,
      dueDate: inv.dueDate,
      isOverdue,
      humanReviewAction: 'Founder must verify bank statement before marking paid.',
      suggestedDraft: draftText
    });
  }
});

// 2. Check Expiring Quotes
quotes.forEach(q => {
  if (q.status === 'Sent' && q.validUntil && q.validUntil <= threeDaysAhead) {
    const draftText = `Dear ${q.clientName}, following up on quotation ${q.id} for ${q.service} (₹${(q.totalAmount || 0).toLocaleString('en-IN')}). The current pricing validity is until ${q.validUntil}. We would be glad to address any queries you or your team might have.`;

    drafts.push({
      type: 'QUOTATION_EXPIRY_REMINDER',
      id: q.id,
      clientName: q.clientName,
      totalAmount: q.totalAmount,
      validUntil: q.validUntil,
      suggestedDraft: draftText
    });
  }
});

return drafts.map(d => ({ json: d }));

// MaxEco Node C.4: Render Human-in-the-Loop Review Draft File (Zero Auto-Messaging)
const fs = require('fs');
const path = require('path');

const items = $input.all().map(i => i.json);
const outDir = path.resolve(process.cwd(), 'docs/reports');
if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

const todayStr = new Date().toISOString().slice(0, 10);
let md = `# MaxEco Follow-Up Review Queue — ${todayStr}\n\n`;
md += `> **MANDATORY POLICY**: No messages are sent automatically. These drafts are generated for founder review only.\n\n`;

items.forEach((item, index) => {
  md += `### ${index + 1}. [${item.type}] ${item.clientName} (${item.id})\n`;
  if (item.amountDue) md += `* **Amount Due**: ₹${item.amountDue.toLocaleString('en-IN')} (Due: ${item.dueDate})\n`;
  if (item.validUntil) md += `* **Quote Expiry**: ${item.validUntil}\n`;
  md += `* **Draft Text**:\n> "${item.suggestedDraft}"\n\n`;
});

const outFilePath = path.join(outDir, `followup-drafts-${todayStr}.md`);
fs.writeFileSync(outFilePath, md, 'utf8');

return [{
  json: {
    status: 'DRAFTS_READY_FOR_FOUNDER_REVIEW',
    totalDrafts: items.length,
    reviewFile: outFilePath,
    timestamp: new Date().toISOString()
  }
}];
